do $$ begin if not exists (select 1 from pg_constraint where conname='mission365_notification_deliveries_unique_channel') then alter table public.mission365_notification_deliveries add constraint mission365_notification_deliveries_unique_channel unique(notification_id,channel);end if;end $$;
create or replace function mission365_private.queue_notification_deliveries() returns trigger language plpgsql security definer set search_path to 'public','pg_temp' as $$ declare p record;begin select in_app_enabled,email_enabled,sms_enabled into p from public.mission365_notification_preferences where user_id=new.user_id;if coalesce(p.in_app_enabled,true) then insert into public.mission365_notification_deliveries(notification_id,channel,status,attempted_at) values(new.id,'in_app','sent',now()) on conflict(notification_id,channel) do nothing;end if;if coalesce(p.email_enabled,true) then insert into public.mission365_notification_deliveries(notification_id,channel,status) values(new.id,'email','queued') on conflict(notification_id,channel) do nothing;end if;if coalesce(p.sms_enabled,false) then insert into public.mission365_notification_deliveries(notification_id,channel,status) values(new.id,'sms','queued') on conflict(notification_id,channel) do nothing;end if;return new;end;$$;
revoke all on function mission365_private.queue_notification_deliveries() from public,anon,authenticated;
drop trigger if exists mission365_notification_delivery_queue on public.mission365_notifications;
create trigger mission365_notification_delivery_queue after insert on public.mission365_notifications for each row execute function mission365_private.queue_notification_deliveries();
